// detailPrimaryAction picks the single state-aware "primary" action for the
// bottom bar. Mirrors TUI semantics:
//   - pending          → start  (forward, primary)
//   - executing        → abort  (the only safe manual move; done is intentionally hidden)
//   - done             → reopen+rerun (both primary; see TaskActionBar)
//   - aborted          → reopen+rerun (both primary; see TaskActionBar)
//   - captured         → triage (cross-project-issue-triage Phase 1 PR-3)
//   - triaged          → ready  (= Go, 逆輸入2: 「triage task を ready にする判断」)
//   - working          → ready  (= Go。2026-08-16 follow-up: triage カードが
//     working に入った後も子を specced にして Go できるようにする。machine.go
//     は working→ready の Manual 遷移を既に持っている — 欠けていたのは配線だけ)
//
// ready itself has no primary action here: the ready→working transition is
// machine-driven (TaskWorkflowService.Dispatch, PR-2) immediately after Go
// commits, so a task resting in ready with no forward button is the
// intended "stuck" signal (機構の不調のサイン — see machine.go's NewMachine
// doc comment), not a missing feature.
//
// parked is deliberately absent from this switch — Wake is not reachable
// through the generic action-send form this function backs (wake_triaged/
// wake_ready are Manual:false; TaskWorkflowService.Wake is its own
// endpoint). TaskActionBar renders parked's Wake button directly instead of
// routing it through detailPrimaryAction/actionPrimaryClass.
//
// Returns ("", "") when no primary action applies.
func detailPrimaryAction(task *orchestrator.Task, availableActions []string) (action, label string) {
	switch task.Status {
	case orchestrator.TaskStatusPending:
		for _, a := range availableActions {
			if a == "start" {
				return "start", "Start"
			}
		}
	case orchestrator.TaskStatusExecuting:
		for _, a := range availableActions {
			if a == "abort" {
				return "abort", "Abort"
			}
		}
	case orchestrator.TaskStatusAborted:
		return "rerun", "Rerun"
	case orchestrator.TaskStatusCaptured:
		for _, a := range availableActions {
			if a == "triage" {
				return "triage", "Triage"
			}
		}
	case orchestrator.TaskStatusTriaged, orchestrator.TaskStatusWorking:
		for _, a := range availableActions {
			if a == "ready" {
				return "ready", "Go"
			}
		}
	}
	return "", ""
}

// actionPrimaryClass picks the visual variant for the primary bottom-bar
// button: blue for forward (start/ready=Go), red for destructive (abort),
// neutral for re-execute (rerun) / triage (a judgment call, not a
// forward-committing one — kept visually lighter than Go).
func actionPrimaryClass(action string) string {
	switch action {
	case "start", "ready":
		return "btn btn-primary"
	case "abort":
		return "btn btn-danger"
	default:
		return "btn btn-secondary"
	}
}

